export function createSessions() {
  const all = [];
  let nextId = 1;

  return {
    open(user) {
      const id = nextId++;
      all.push({ id, user, closed: false });
      return id;
    },
    close(id) {
      const session = all.find((s) => s.id === id);
      if (session) {
        session.closed = true;
      }
    },
    activeUsers() {
      return all.filter((s) => !s.closed).map((s) => s.user);
    },
    stored() {
      return all.length;
    },
  };
}
